'use client';

import React from 'react';
import Image from 'next/image';
import { Button } from '@/components/ui/button';
import { Card, CardContent } from '@/components/ui/card';
import { Badge } from '@/components/ui/badge';
import { Vehicle } from '@/common/interfaces';
import { useRouter } from '@/localization/navigation';
import { useTranslations } from 'next-intl';

interface MostPopularCarProps {
  vehicle: Vehicle & { bookingCount: number };
}

const MostPopularCar: React.FC<MostPopularCarProps> = ({ vehicle }) => {
  const router = useRouter();
  const t = useTranslations('home');

  const formatBookingCount = (count: number) => {
    if (count >= 1000000) {
      return `Over ${(count / 1000000).toFixed(1)}M+ People Booked...`;
    } else if (count >= 1000) {
      return `Over ${(count / 1000).toFixed(1)}L+ People Booked...`;
    }
    return `${count}+ People Booked...`;
  };

  const getTransmissionDisplay = (transmission: string) => {
    return transmission.charAt(0).toUpperCase() + transmission.slice(1).toLowerCase();
  };

  const getDrivetrainDisplay = (drivetrain: string) => {
    switch (drivetrain) {
      case 'FWD': return 'FWD';
      case 'RWD': return 'RWD';
      case 'AWD': return 'AWD';
      case '4WD': return '4WD';
      default: return drivetrain;
    }
  };

  const primaryImage = vehicle.media?.find(img => img.isPrimary) || vehicle.media?.[0];
  const getImageUrl = (image: any) => {
    if (!image) return null;
    
    const url = image?.frontImage || image?.backImage || image?.leftSideImage || image?.rightSideImage;
    
    // Return null if no URL found, to trigger fallback UI
    if (!url) return null;
    
    // If URL is already absolute (starts with http), return as-is
    if (url.startsWith('http')) return url;
    
    // If it's a relative path, ensure it starts with /
    return url.startsWith('/') ? url : `/${url}`;
  };

  const imageUrl = getImageUrl(primaryImage);

  return (
    <Card className="w-full max-w-md mx-auto overflow-hidden">
      <CardContent className="p-0">
        {/* Header with Hot Choice Badge */}
        <div className="relative">
          <div className="absolute top-4 left-4 z-10">
            <Badge className="bg-orange-500 hover:bg-orange-600 text-white font-semibold px-3 py-1">
              Hot Choice
            </Badge>
          </div>
          
          {/* Car Image */}
          <div className="relative h-48 w-full">
            {imageUrl ? (
              <Image
                src={imageUrl}
                alt={`${vehicle.make} ${vehicle.model}`}
                fill
                className="object-cover"
                sizes="(max-width: 768px) 100vw, (max-width: 1200px) 50vw, 33vw"
              />
            ) : (
              <div className="w-full h-full bg-gray-200 flex items-center justify-center">
                <span className="text-gray-500">No Image Available</span>
              </div>
            )}
          </div>
        </div>

        {/* Car Details */}
        <div className="p-6 space-y-4">
          {/* Title and Booking Stats */}
          <div className="space-y-2">
            <h3 className="text-xl font-bold text-gray-900">
              {vehicle.make} {vehicle.model} {vehicle.year} {vehicle.trim}
            </h3>
            <p className="text-sm text-orange-600 font-medium">
              {formatBookingCount(vehicle.bookingCount)}
            </p>
          </div>

          {/* Specifications Grid */}
          <div className="grid grid-cols-2 gap-4 text-sm">
            <div className="flex items-center space-x-2">
              <span className="text-gray-600">Seating:</span>
              <span className="font-medium">{vehicle.passengerCapacity}</span>
            </div>
            <div className="flex items-center space-x-2">
              <span className="text-gray-600">Transmission:</span>
              <span className="font-medium">{getTransmissionDisplay(vehicle.transmission)}</span>
            </div>
            <div className="flex items-center space-x-2">
              <span className="text-gray-600">Drive:</span>
              <span className="font-medium">{getDrivetrainDisplay(vehicle.drivetrain)}</span>
            </div>
            <div className="flex items-center space-x-2">
              <span className="text-gray-600">Mileage:</span>
              <span className="font-medium">{vehicle.fuelConsumption}</span>
            </div>
          </div>

          {/* Action Buttons */}
          <div className="flex gap-3 pt-2">
            <Button
              variant="outline"
              className="flex-1"
              onClick={() => router.push(`/vehicles/${vehicle.id}`)}
            >
              View Car Details
            </Button>
            <Button
              className="flex-1"
              onClick={() => router.push(`/vehicles/${vehicle.id}?action=book`)}
            >
              Book Car
            </Button>
          </div>
        </div>
      </CardContent>
    </Card>
  );
};

export default MostPopularCar;
